import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> nilai = new ArrayList<>();
        nilai.add(80);
        nilai.add(75);
        nilai.add(90);
        nilai.set(1, 85);
        nilai.add(0, 100);
        System.out.println(nilai);
        System.out.println(nilai.size());
    }
}

